describe('Notifications Empty State', () => {
    beforeEach(() => {
        cy.visit('/notifications');
    });

    it('should display an empty state message when there are no notifications', () => {
        cy.intercept('GET', '/api/notifications', []).as('getNotifications');
        cy.wait('@getNotifications');
        cy.get('.empty-state').should('be.visible');
        cy.get('.empty-state').contains('You have no notifications');
    });

    it('should not display any notification items when there are no notifications', () => {
        cy.intercept('GET', '/api/notifications', []).as('getNotifications');
        cy.wait('@getNotifications');
        cy.get('.notification-item').should('not.exist');
    });
});
